.content-section {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 56px 24px;
  background: var(--color-surface);
}

.service-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-top: 28px;
  padding: 0;
  list-style: none;
}
